import {test,expect,type Page,type APIRequestContext,type TestInfo} from '@playwright/test';
import {randomUUID,createHash} from 'node:crypto';
import {writeFile} from 'node:fs/promises';
import {blankContent,blankRequirement} from '@/domain/tasks/types';
import {blankCommon,blankContext} from '@/domain/products/types';
import type {TaskDetail} from '@/server/tasks/service';
import type {CampaignDetail} from '@/server/campaigns/contracts';
import type {CampaignDraft,MenuDraft,SourceText} from '@/domain/campaigns/types';
import type {ProductDetail} from '@/server/products/service';
import type {SubmissionWorkspace} from '@/server/submissions/contracts';
export const ctx='ctx-jp-a-luna',canary='G12_UI_PRIVATE_CANARY';
export const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aS0cAAAAASUVORK5CYII=','base64');
export async function login(page:Page,email='admin@example.test'){await page.context().clearCookies();await page.goto('/login');await page.getByRole('textbox',{name:'이메일',exact:true}).fill(email);await page.getByLabel('비밀번호',{exact:true}).fill('Demo-Hale-2026!');await page.getByRole('button',{name:'로그인',exact:true}).click();await expect(page).toHaveURL(/\/$/);}
export async function mutation(r:APIRequestContext,url:string,data:unknown,method='POST'){const token=await(await r.get('/api/auth/csrf')).json();return r.fetch(url,{method,data,headers:{Origin:`http://127.0.0.1:${process.env.E2E_PORT}`,'X-CSRF-Token':token.csrfToken}});}
export async function json<T>(r:APIRequestContext,url:string):Promise<T>{const response=await r.get(url);expect(response.status(),await response.text()).toBe(200);return response.json();}
export async function cmd(page:Page,id:string,command:string,extra:Record<string,unknown>={}){const d=await json<CampaignDetail>(page.request,`/api/campaigns/${id}`);const r=await mutation(page.request,'/api/campaigns',{command,contextId:ctx,taskId:d.taskId,campaignId:id,expectedRevision:d.revision,idempotencyKey:randomUUID(),...extra});expect(r.status(),await r.text()).toBe(200);return (await r.json()).ids as string[];}
export async function taskCommand(page:Page,id:string,command:string,extra:Record<string,unknown>={}){const d=await json<TaskDetail>(page.request,`/api/tasks/${id}?context=${ctx}`);const r=await mutation(page.request,`/api/tasks/${id}`,{command,expectedRevision:d.task.revision,idempotencyKey:randomUUID(),...extra});expect(r.status(),await r.text()).toBe(200);return(await r.json()).ids as string[];}
export async function setup(page:Page){await login(page);const p1=await json<ProductDetail>(page.request,`/api/products/product-serum?context=${ctx}`),created=await mutation(page.request,'/api/products',{contextId:ctx,brandId:p1.context.data.brandId,common:{...blankCommon(),name:'미선택 배포 상품 '+randomUUID().slice(0,5),code:'UI-'+randomUUID()},fields:blankContext(),idempotencyKey:randomUUID()});expect(created.status(),await created.text()).toBe(201);const p2=await json<ProductDetail>(page.request,`/api/products/${(await created.json()).ids[0]}?context=${ctx}`);
 const content={...blankContent(),title:'행사 UI 합성 '+randomUUID().slice(0,6),description:'세 메뉴의 실제 자료 요청',deadline:{...blankContent().deadline,responsibleUserId:'user-gsg'},requirements:[{...blankRequirement('proof','file'),label:'실행 사진'},{...blankRequirement('url','link'),label:'게시 URL'},{...blankRequirement('other','number'),label:'배포 메뉴 수량'}]};const r=await mutation(page.request,'/api/tasks',{category:'spot',content,targets:[{contextId:ctx,ownerId:'user-gsg',assigneeId:'user-luna',coAssigneeIds:['user-co'],productIds:[p1.productId,p2.productId]}],idempotencyKey:randomUUID()});expect(r.status(),await r.text()).toBe(201);const taskId=(await r.json()).ids[0] as string;await taskCommand(page,taskId,'publish');return{taskId,p1,p2,content};}
export const source=():SourceText=>({source:canary,sourceVersion:'catalog-v1',locator:'p.3',language:'ja',originalText:canary+' 原文10000円',translatedText:canary+' 번역',fileVersionIds:[]});
export async function seeded(page:Page){const x=await setup(page),r=await mutation(page.request,'/api/campaigns',{command:'save_catalog',contextId:ctx,catalogId:null,expectedRevision:0,idempotencyKey:randomUUID(),draft:{title:'합성 카탈로그',versionLabel:'2026 v1',source:source()}});expect(r.status()).toBe(200);const catalogVersionId=(await r.json()).ids[1];
 const menu=(name:string,p:ProductDetail,first=false):MenuDraft=>{const product={productId:p.productId,productVersionId:p.commonVersionId,contextProductVersionId:p.contextVersionId,productUseId:null,sampleVariant:'샘플'};return {identity:{catalogVersionId,menuKey:randomUUID(),menuName:name,menuNumber:'1'},sourceStatements:[{id:'p1',field:'price',rawValue:'10000円',source:source()},{id:'p2',field:'price',rawValue:'12000円',source:{...source(),sourceVersion:'email-v2'}}],conflicts:[{field:'price',statementIds:['p1','p2'],state:'needs_confirmation',resolution:''}],conditions:{state:'confirmed',sourceStatementIds:['p1','p2'],publicExplanation:'합성 공개 안내 · 현재 비용 미정',cost:{amount:null,currency:null,taxIncluded:'unknown'},discount:'할인 확인 중',points:'포인트 확인 중',cancellationTerms:'신청 후 취소 협의',schedules:[]},templateVersionId:null,request:{...x.content,internalOriginal:canary,internalMemo:canary,requirements:first?x.content.requirements.slice(0,2):x.content.requirements.slice(2)},products:[product],physical:first?[{key:'shoot',destination:'촬영 스튜디오 A',purpose:'촬영용',product,requestedQuantity:'1',unit:'개',plannedShip:x.content.deadline,plannedArrival:x.content.deadline},{key:'distribution',destination:'배포 센터 B',purpose:'배포용',product,requestedQuantity:'100',unit:'개',plannedShip:x.content.deadline,plannedArrival:x.content.deadline}]:[],followups:first?[{key:'photo',kind:'execution_photo',requirementKey:'proof',deadline:x.content.deadline},{key:'url',kind:'publication_url',requirementKey:'url',deadline:x.content.deadline}]:[]};};const draft:CampaignDraft={title:'합성 공개 행사',menus:[menu('촬영 행사',x.p1,true),menu('배포 행사',x.p2),menu('교육 행사',x.p2)]};const saved=await mutation(page.request,'/api/campaigns',{command:'save',contextId:ctx,taskId:x.taskId,campaignId:null,expectedRevision:0,idempotencyKey:randomUUID(),draft});expect(saved.status(),await saved.text()).toBe(200);const id=(await saved.json()).ids[0] as string;const ids=await cmd(page,id,'publish');return{...x,id,versionId:ids[1],draft};}
export const href=(taskId:string,id?:string)=>`/tasks/${taskId}/campaigns?context=${ctx}${id?'&campaign='+id:''}`;
export async function open(page:Page,taskId:string,id?:string){await page.goto(href(taskId,id));await expect(page.getByText('현재 권한과 저장된 내용을 확인하는 중입니다.',{exact:true})).toHaveCount(0);await expect(page.getByRole('heading',{name:'행사 자료를 열 수 없습니다',exact:true})).toHaveCount(0);}
export async function tab(page:Page,name:string){await page.getByRole('navigation',{name:'행사 화면',exact:true}).getByRole('button',{name,exact:true}).click();}
export async function saved(page:Page){await expect(page.getByRole('navigation',{name:'행사 화면',exact:true}).getByRole('button').first()).toBeEnabled();await expect(page.getByRole('status').filter({hasText:'기록을 저장했습니다.'})).toBeVisible();}
export async function chooseOne(page:Page,taskId:string,id:string){await login(page,'luna@example.test');await open(page,taskId,id);await tab(page,'참여·사실 기록');await page.getByRole('group',{name:'참여할 메뉴',exact:true}).getByRole('checkbox',{name:'1 · 촬영 행사',exact:true}).check();await page.getByRole('button',{name:'참여 회신 저장',exact:true}).click();await saved(page);}
export async function snapshot(page:Page,info:TestInfo){await writeFile(info.outputPath('final-private.html'),await page.content());await page.screenshot({path:info.outputPath(info.status===info.expectedStatus?'final-private.png':'failure-private.png'),fullPage:true});await page.context().tracing.stop({path:info.outputPath('journey-private.zip')});}
export function journeys(){test.beforeEach(async({page})=>{await page.context().tracing.start({screenshots:true,snapshots:true,sources:true});});test.afterEach(async({page},info)=>snapshot(page,info));}
export async function actualSubmission(page:Page,taskId:string){let w=await json<SubmissionWorkspace>(page.request,`/api/tasks/${taskId}/submissions`);const csrf=await(await page.request.get('/api/auth/csrf')).json();const r=await page.request.post(`/api/tasks/${taskId}/submission-files?requestId=${w.request.id}`,{multipart:{clientItemIds:randomUUID(),files:{name:'실행.png',mimeType:'image/png',buffer:png}},headers:{Origin:`http://127.0.0.1:${process.env.E2E_PORT}`,'X-CSRF-Token':csrf.csrfToken}});expect(r.status(),await r.text()).toBe(200);const file=(await r.json()).items[0].file;const p=await json<ProductDetail>(page.request,`/api/products/product-serum?context=${ctx}`);const content={answers:[{requestId:w.request.id,requirementKey:'proof',productId:null,type:'file',input:{fileVersionIds:[file.id]}},{requestId:w.request.id,requirementKey:'url',productId:null,type:'link',input:{url:'https://example.test/published',description:'합성 게시 URL',contentFixed:false,fixedReference:null}}],narrative:'실제 제출 원문',links:[],artifacts:[{fileVersionId:file.id,role:'evidence',answer:{requirementKey:'proof',productId:null}}],productSelections:[{productId:p.productId,expectedCommonRevision:p.commonRevision,expectedContextRevision:p.contextRevision,bindingIds:[],retailPriceVersionId:null,asOfDate:'2026-09-21'}]};const save=await mutation(page.request,`/api/tasks/${taskId}/submission-draft`,{command:'save',baseRequestId:w.request.id,expectedDraftRevision:w.draft?.revision??0,content,idempotencyKey:randomUUID()});expect(save.status(),await save.text()).toBe(200);w=await json(page.request,`/api/tasks/${taskId}/submissions`);const submit=await mutation(page.request,`/api/tasks/${taskId}/submissions`,{baseRequestId:w.request.id,expectedDraftRevision:w.draft!.revision,expectedTaskRevision:w.taskRevision,mode:'full',idempotencyKey:randomUUID()});expect(submit.status(),await submit.text()).toBe(201);return{w:await json<SubmissionWorkspace>(page.request,`/api/tasks/${taskId}/submissions`),file,hash:createHash('sha256').update(png).digest('hex')};}
